class Solution:
    def checkInclusion(self, s1: str, s2: str) -> bool:
        m, n = len(s1), len(s2)
        if m > n:
            return False

        count = Counter(s1)
        s = 0
        l = 0

        for r in range(n):
            if s2[r] in count:
                count[s2[r]] -= 1
            s += 1

            if s == m:
                flag = True
                for freq in count.values():
                    if freq != 0:
                        flag = False
                if flag:
                    return flag

                if s2[l] in count:
                    count[s2[l]] += 1
                l += 1
                s -= 1

        return False
